{"command":"cat <<'EOF' >> main.c
char **target_files = NULL;
int num_target_files = 0;

void add_watch_path(char *path, int is_dir) {
    if (num_watches >= watches_cap) {
        watches_cap = watches_cap == 0 ? 256 : watches_cap * 2;
        watches = realloc(watches, watches_cap * sizeof(WatchedFile));
    }
    watches[num_watches].path = strdup(path);
    int mask = IN_MODIFY | IN_ATTRIB | IN_CLOSE_WRITE | IN_DELETE_SELF | IN_MOVE_SELF;
    if (is_dir) mask |= IN_CREATE | IN_DELETE | IN_MOVED_TO | IN_MOVED_FROM;
    int wd = inotify_add_watch(inotify_fd, path, mask);
    watches[num_watches].wd = wd;
    watches[num_watches].is_dir = is_dir;
    num_watches++;
}

void read_files() {
    char line[PATH_MAX];
    while (fgets(line, sizeof(line), stdin)) {
        size_t len = strlen(line);
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) len--;
        line[len] = '\0';
        if (len == 0) continue;

        struct stat st;
        if (stat(line, &st) != 0) {
            fprintf(stderr, "%s: unable to stat '%s'\n", progname, line);
            continue;
        }

        target_files = realloc(target_files, (num_target_files + 1) * sizeof(char *));
        target_files[num_target_files++] = strdup(line);

        if (S_ISDIR(st.st_mode)) {
            add_watch_path(line, 1);
        } else {
            add_watch_path(line, 0);
            if (flag_d) {
                char *copy = strdup(line);
                char *dir = dirname(copy);
                add_watch_path(dir, 1);
                free(copy);
            }
        }
    }
}
EOF"}

