        snprintf(buf, sizeof(buf), "exit|%d|%s\n", WEXITSTATUS(status), cmd_name);
    } else if (WIFSIGNALED(status)) {
        snprintf(buf, sizeof(buf), "signal|%d|%s\n", WTERMSIG(status), cmd_name);
