{"command":"cat <<'EOF' > main.c
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/inotify.h>
#include <poll.h>
#include <termios.h>
#include <signal.h>
#include <errno.h>
#include <libgen.h>
#include <limits.h>
#include <ctype.h>
#include <sys/signalfd.h>

char *progname = "entr";

int flag_a = 0, flag_c = 0, flag_cc = 0, flag_d = 0, flag_dd = 0;
int flag_n = 0, flag_p = 0, flag_r = 0, flag_s = 0, flag_x = 0, flag_xx = 0, flag_z = 0;

int restart_signal = SIGTERM;
int inotify_fd;
int tty_fd = -1;
int sig_fd = -1;
struct termios orig_termios;

typedef struct {
    char *path;
    int wd;
    int is_dir;
} WatchedFile;

WatchedFile *watches = NULL;
int num_watches = 0;
int watches_cap = 0;

char **target_files = NULL;
int num_target_files = 0;
int awk_fd = -1;

int str_to_sig(const char *name) {
    if (!name) return SIGTERM;
    if (strncmp(name, "SIG", 3) == 0) name += 3;
    if (strcmp(name, "HUP") == 0) return SIGHUP;
    if (strcmp(name, "INT") == 0) return SIGINT;
    if (strcmp(name, "QUIT") == 0) return SIGQUIT;
    if (strcmp(name, "TERM") == 0) return SIGTERM;
    if (strcmp(name, "USR1") == 0) return SIGUSR1;
    if (strcmp(name, "USR2") == 0) return SIGUSR2;
    return -1;
}

void setup_tty() {
    if (flag_n) return;
    tty_fd = open("/dev/tty", O_RDWR);
    if (tty_fd < 0) {
        fprintf(stderr, "%s: unable to get terminal attributes, use '-n' to run non-interactively\n", progname);
        exit(1);
    }
    tcgetattr(tty_fd, &orig_termios);
    struct termios raw = orig_termios;
    raw.c_lflag &= ~(ECHO | ICANON);
    raw.c_cc[VMIN] = 1;
    raw.c_cc[VTIME] = 0;
    tcsetattr(tty_fd, TCSANOW, &raw);
}

void restore_tty() {
    if (tty_fd >= 0) tcsetattr(tty_fd, TCSANOW, &orig_termios);
}

void cleanup_tty() {
    restore_tty();
}

void parse_args(int argc, char **argv, int *optind_out) {
    int i;
    for (i = 1; i < argc; i++) {
        if (argv[i][0] != '-' || argv[i][1] == '\0') break;
        for (int j = 1; argv[i][j]; j++) {
            switch (argv[i][j]) {
                case 'a': flag_a = 1; break;
                case 'c': if (flag_c) flag_cc = 1; flag_c = 1; break;
                case 'd': if (flag_d) flag_dd = 1; flag_d = 1; break;
                case 'n': flag_n = 1; break;
                case 'p': flag_p = 1; break;
                case 'r': flag_r = 1; break;
                case 's': flag_s = 1; break;
                case 'x': if (flag_x) flag_xx = 1; flag_x = 1; break;
                case 'z': flag_z = 1; break;
                default: exit(1);
            }
        }
    }
    *optind_out = i;
    if (flag_r && flag_x) {
        fprintf(stderr, "%s: -r and -x may not be combined\n", progname);
        exit(1);
    }
}

void add_watch_path(char *path, int is_dir) {
    if (num_watches >= watches_cap) {
        watches_cap = watches_cap == 0 ? 256 : watches_cap * 2;
        watches = realloc(watches, watches_cap * sizeof(WatchedFile));
    }
    int mask = IN_MODIFY | IN_ATTRIB | IN_CLOSE_WRITE | IN_DELETE_SELF | IN_MOVE_SELF;
    if (is_dir) mask |= IN_CREATE | IN_DELETE | IN_MOVED_TO | IN_MOVED_FROM;
    int flags = 0;
    if (!getenv("ENTR_FOLLOW_SYMLINK")) flags |= IN_DONT_FOLLOW;

    int wd = inotify_add_watch(inotify_fd, path, mask | flags);
    watches[num_watches].path = strdup(path);
    watches[num_watches].wd = wd;
    watches[num_watches].is_dir = is_dir;
    num_watches++;
}

void read_files() {
    char line[PATH_MAX];
    int has_stat_error = 0;
    while (fgets(line, sizeof(line), stdin)) {
        size_t len = strlen(line);
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) len--;
        line[len] = '\0';
        if (len == 0) continue;

        struct stat st;
        if (stat(line, &st) != 0) {
            fprintf(stderr, "%s: unable to stat '%s'\n", progname, line);
            has_stat_error = 1;
            continue;
        }

        target_files = realloc(target_files, (num_target_files + 1) * sizeof(char *));
        target_files[num_target_files++] = strdup(line);

        if (S_ISDIR(st.st_mode)) {
            add_watch_path(line, 1);
        } else {
            add_watch_path(line, 0);
            char *copy = strdup(line);
            char *dir = dirname(copy);
            add_watch_path(dir, 1);
            free(copy);
        }
    }
    if (has_stat_error || num_target_files == 0) {
        fprintf(stderr, "%s: No regular files to watch\n", progname);
        exit(1);
    }
}

void setup_awk() {
    if (!flag_x) return;
    char *script = getenv("ENTR_STATUS_SCRIPT");
    if (!script) {
        char *home = getenv("HOME");
        if (home) {
            char path[PATH_MAX];
            snprintf(path, sizeof(path), "%s/.entr/status.awk", home);
            script = strdup(path);
        } else {
            script = strdup("/tmp/status.awk");
        }
    }
    if (access(script, F_OK) != 0) {
        char *dir = strdup(script);
        char *dname = dirname(dir);
        char mkdir_cmd[PATH_MAX + 16];
        snprintf(mkdir_cmd, sizeof(mkdir_cmd), "mkdir -p '%s'", dname);
        system(mkdir_cmd);
        free(dir);

        FILE *f = fopen(script, "w");
        if (f) {
            fprintf(f, "# http://eradman.com/entrproject/status-filters.html\n");
            fprintf(f, "/^signal/ { print $3, \"terminated by signal\", $2; }\n");
            fprintf(f, "/^exit/ { print $3, \"returned exit code\", $2; }\n");
            fclose(f);
            fprintf(stderr, "%s: created '%s'\n", progname, script);
        }
    }

    int p[2];
    pipe(p);
    if (fork() == 0) {
        dup2(p[0], 0);
        close(p[0]); close(p[1]);
        if (flag_xx) {
            execlp("awk", "awk", "-F", "|", "-f", script, NULL);
        } else {
            execlp("awk", "awk", "-F", "|", "-f", script, "-S", NULL);
        }
        exit(1);
    }
    close(p[0]);
    awk_fd = p[1];
}

void report_status(int status, char *cmd_name) {
    if (awk_fd < 0) return;
    char buf[256];
    if (WIFEXITED(status)) {
        snprintf(buf, sizeof(buf), "exit|%d|%s\n", WEXITSTATUS(status), cmd_name);
    } else if (WIFSIGNALED(status)) {
        snprintf(buf, sizeof(buf), "signal|%d|%s\n", WTERMSIG(status), cmd_name);
    }
    write(awk_fd, buf, strlen(buf));
}

int child_pid = 0;
void kill_child() {
    if (child_pid) {
        if (flag_r) kill(-child_pid, restart_signal);
        else kill(child_pid, restart_signal);

        int status;
        while (waitpid(child_pid, &status, 0) == -1 && errno == EINTR);
        child_pid = 0;
    }
}

int run_utility(int argc, char **argv, int optind, char *triggered_file) {
    if (flag_c) {
        printf("\x1b[2J\x1b[H");
        if (flag_cc) printf("\x1b[3J");
        fflush(stdout);
    }

    int pid = fork();
    if (pid == 0) {
        if (flag_r) setpgid(0, 0);
        restore_tty();
        if (!getenv("PAGER")) setenv("PAGER", "/bin/cat", 1);

        int cmd_argc = argc - optind;
        char **cmd_argv = malloc((cmd_argc + 1) * sizeof(char *));
        for (int i = 0; i < cmd_argc; i++) cmd_argv[i] = argv[optind + i];
        cmd_argv[cmd_argc] = NULL;

        if (flag_s) {
            char *shell = getenv("SHELL");
            if (!shell) shell = "/bin/sh";
            execl(shell, shell, "-c", cmd_argv[0], triggered_file ? triggered_file : target_files[0], NULL);
            exit(127);
        } else {
            int replaced = 0;
            for (int i = 0; i < cmd_argc; i++) {
                if (!replaced && strcmp(cmd_argv[i], "/_") == 0) {
                    cmd_argv[i] = triggered_file ? triggered_file : target_files[0];
                    replaced = 1;
                }
            }
            execvp(cmd_argv[0], cmd_argv);
            exit(127);
        }
    }
    child_pid = pid;
    return pid;
}

void setup_signals() {
    sigset_t mask;
    sigemptyset(&mask);
    sigaddset(&mask, SIGCHLD);
    sigaddset(&mask, SIGINT);
    sigaddset(&mask, SIGTERM);
    sigprocmask(SIG_BLOCK, &mask, NULL);
    sig_fd = signalfd(-1, &mask, SFD_NONBLOCK);
}

int main(int argc, char **argv) {
    if (argc > 0) {
        char *copy = strdup(argv[0]);
        progname = strdup(basename(copy));
        free(copy);
    }
    int optind = 1;
    parse_args(argc, argv, &optind);

    char *restart_env = getenv("ENTR_RESTART_SIGNAL");
    if (restart_env) {
        int sig = str_to_sig(restart_env);
        if (sig < 0) {
            fprintf(stderr, "%s: unrecognized signal: %s <> (HUP, INT, QUIT, TERM, USR1, USR2)\n", progname, restart_env);
            exit(1);
        }
        restart_signal = sig;
    }

    if (optind >= argc) {
        fprintf(stderr, "%s: missing utility\n", progname);
        exit(1);
    }

    inotify_fd = inotify_init1(IN_NONBLOCK);
    if (inotify_fd < 0) {
        perror("inotify_init");
        exit(1);
    }

    if (!flag_n) setup_tty();
    read_files();
    setup_awk();
    setup_signals();

    if (getenv("EV_TRACE")) {
        FILE *f = fopen("/proc/sys/fs/inotify/max_user_watches", "r");
        if (f) {
            int open_max = 0;
