int flag_n = 0, flag_p = 0, flag_r = 0, flag_s = 0, flag_x = 0, flag_xx = 0, flag_z = 0;

int restart_signal = SIGTERM;
int inotify_fd;
int tty_fd = -1;
int sig_fd = -1;
